WITH flattened_attrs AS (SELECT id, created_at, coupon_codes, SIZE(items) AS num_items, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg, TRANSFORM(items, item -> item.product_id) AS product_ids FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'SPRING10')) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, DATE_TRUNC('HOUR', created_at) AS hour_window, AVG(num_items) AS avg_num_items, MIN(created_at) AS started_at, ROUND(AVG(weight_kg), 2) AS avg_weight_kg, MIN(created_at) AS first_seen, COUNT(*) AS num_rows FROM flattened_attrs GROUP BY DATE_TRUNC('DAY', created_at), DATE_TRUNC('HOUR', created_at) ORDER BY hour_window NULLS FIRST
